"""Tests for the nsd-control parser's parse() function."""

import pytest

from jc.parsers.nsd_control import parse


def test_parse_empty_and_whitespace_only_input():
    assert parse("", quiet=True) == []
    assert parse("   \n\t\r\n  ", quiet=True) == []


def test_parse_ok_command_lines_are_trimmed_and_collected():
    assert parse("  ok  \nok\n", quiet=True) == [
        {"command": "ok"},
        {"command": "ok"},
    ]


def test_parse_status_raw_preserves_unprocessed_numeric_strings():
    data = "version: 4.6.2\nverbosity: 2\nratelimit: 0\n"

    assert parse(data, raw=True, quiet=True) == [
        {
            "version": "4.6.2",
            "verbosity": " 2",
            "ratelimit": " 0",
        }
    ]


def test_parse_status_processed_converts_top_level_numbers():
    data = "version: 4.6.2\nverbosity: 2\nratelimit: 100\n"

    result = parse(data, quiet=True)

    assert result == [{"version": "4.6.2", "verbosity": 2, "ratelimit": 100}]
    assert isinstance(result[0]["verbosity"], int)
    assert isinstance(result[0]["ratelimit"], int)


def test_parse_cookie_secrets():
    data = (
        "active : 5414f1a7d8480347b4c01c806e9f442f\n"
        "staging: 7b4c01c806e9f442f5414f1a7d848034\n"
    )
    expected = [
        {
            "active": "5414f1a7d8480347b4c01c806e9f442f",
            "staging": "7b4c01c806e9f442f5414f1a7d848034",
        }
    ]

    assert parse(data, raw=True, quiet=True) == expected
    assert parse(data, quiet=True) == expected


def test_parse_tsig_key_removes_surrounding_quotes():
    data = (
        'key: name: "test-tsig" secret: '
        '"83d61b962c20f5352955dc197d3db6d3" algorithm: hmac-md5\n'
    )
    expected = [
        {
            "key": {
                "name": "test-tsig",
                "secret": "83d61b962c20f5352955dc197d3db6d3",
                "algorithm": "hmac-md5",
            }
        }
    ]

    assert parse(data, quiet=True) == expected


def test_parse_zonestatus_wait_and_transfer_records():
    data = (
        "zone:\tsunet.se\n"
        '\tstate: ok\n'
        '\tserved-serial: "2023091302 since 2023-09-14T00:50:11"\n'
        '\tcommit-serial: "2023091302 since 2023-09-14T07:04:05"\n'
        '\twait: "27023 sec between attempts"\n'
        "zone:\tsunet.dev\n"
        "\tstate: refreshing\n"
        '\tserved-serial: "2023095893 since 2024-10-10T10:10:35"\n'
        '\tcommit-serial: "2023095893 since 2024-10-18T10:00:45"\n'
        '\tnotified-serial: "2023095880 since 2024-10-19T06:11:35"\n'
        '\ttransfer: "TCP connected to 192.168.1.100"\n'
    )
    expected = [
        {
            "zone": "sunet.se",
            "status": {
                "state": "ok",
                "served-serial": "2023091302 since 2023-09-14T00:50:11",
                "commit-serial": "2023091302 since 2023-09-14T07:04:05",
                "wait": "27023 sec between attempts",
            },
        },
        {
            "zone": "sunet.dev",
            "status": {
                "state": "refreshing",
                "served-serial": "2023095893 since 2024-10-10T10:10:35",
                "commit-serial": "2023095893 since 2024-10-18T10:00:45",
                "notified-serial": "2023095880 since 2024-10-19T06:11:35",
                "transfer": "TCP connected to 192.168.1.100",
            },
        },
    ]

    assert parse(data, raw=True, quiet=True) == expected
    assert parse(data, quiet=True) == expected


def test_parse_zonestatus_catalog_member_fields():
    data = (
