        "\tpattern: example.catalog\n"
        "\tcatalog-member-id: 4b6f6ce2de5929e4.zones.example.catalog.\n"
        "\tstate: ok\n"
        '\tserved-serial: "1705484863 since 2024-01-17T13:06:02"\n'
