        "num.queries=109\n"
        "time.boot=456687.800773\n"
        "size.db.mem=862619640\n"
        "zone.slave=1\n"
    )
    expected = [
        {
            "server0.queries": 109,
            "num.queries": 109,
            "time.boot": 456687.800773,
