    assert isinstance(result[0]["time.boot"], float)
    assert isinstance(result[0]["num.queries"], int)


def test_parse_ignores_unknown_lines_and_blank_lines_between_records():
    data = "  ok\ngarbage\nsome arbitrary text\n\nfoo=bar\n"

    assert parse(data, quiet=True) == [{"command": "ok"}]


def test_parse_mixed_sections_emits_stats_after_immediately_completed_records():
    data = (
        "version: 4.6.2\n"
        "verbosity: 3\n"
        "ratelimit: 5\n"
        "num.queries=7\n"
        "time.elapsed=1.5\n"
    )

    assert parse(data, quiet=True) == [
        {"version": "4.6.2", "verbosity": 3, "ratelimit": 5},
        {"num.queries": 7, "time.elapsed": 1.5},
    ]


@pytest.mark.parametrize("invalid_data", [None, 123, 1.5, [], {}, b"ok\n"])
def test_parse_rejects_non_string_input(invalid_data):
    with pytest.raises(TypeError, match="Input data must be a 'str' object"):
        parse(invalid_data, quiet=True)


def test_parse_quiet_suppresses_incompatibility_warning(monkeypatch, capsys):
    monkeypatch.setattr(
        "jc.parsers.nsd_control.jc.utils.is_compatible", lambda _compatible: False
    )

