        {
            "version": "4.6.2",
            "verbosity": " 2",
            "ratelimit": " 0",
        }
    ]


def test_parse_status_processed_converts_top_level_numbers():
    data = "version: 4.6.2\nverbosity: 2\nratelimit: 100\n"

    result = parse(data, quiet=True)

    assert result == [{"version": "4.6.2", "verbosity": 2, "ratelimit": 100}]
    assert isinstance(result[0]["verbosity"], int)
    assert isinstance(result[0]["ratelimit"], int)


