def test_parse_zonestatus_wait_and_transfer_records():
    data = (
        "zone:\tsunet.se\n"
        '\tstate: ok\n'
        '\tserved-serial: "2023091302 since 2023-09-14T00:50:11"\n'
        '\tcommit-serial: "2023091302 since 2023-09-14T07:04:05"\n'
        '\twait: "27023 sec between attempts"\n'
        "zone:\tsunet.dev\n"
        "\tstate: refreshing\n"
        '\tserved-serial: "2023095893 since 2024-10-10T10:10:35"\n'
        '\tcommit-serial: "2023095893 since 2024-10-18T10:00:45"\n'
        '\tnotified-serial: "2023095880 since 2024-10-19T06:11:35"\n'
        '\ttransfer: "TCP connected to 192.168.1.100"\n'
    )
    expected = [
        {
            "zone": "sunet.se",
            "status": {
                "state": "ok",
                "served-serial": "2023091302 since 2023-09-14T00:50:11",
                "commit-serial": "2023091302 since 2023-09-14T07:04:05",
                "wait": "27023 sec between attempts",
            },
        },
        {
            "zone": "sunet.dev",
            "status": {
                "state": "refreshing",
                "served-serial": "2023095893 since 2024-10-10T10:10:35",
                "commit-serial": "2023095893 since 2024-10-18T10:00:45",
                "notified-serial": "2023095880 since 2024-10-19T06:11:35",
                "transfer": "TCP connected to 192.168.1.100",
            },
        },
    ]

    assert parse(data, raw=True, quiet=True) == expected
    assert parse(data, quiet=True) == expected


