def test_parse_statistics_uses_float_for_time_and_int_for_other_values():
    data = (
        "server0.queries=109\n"
        "num.queries=109\n"
        "time.boot=456687.800773\n"
        "size.db.mem=862619640\n"
        "zone.slave=1\n"
    )
    expected = [
        {
            "server0.queries": 109,
            "num.queries": 109,
            "time.boot": 456687.800773,
            "size.db.mem": 862619640,
            "zone.slave": 1,
        }
    ]

    result = parse(data, quiet=True)

    assert result == expected
    assert isinstance(result[0]["time.boot"], float)
    assert isinstance(result[0]["num.queries"], int)


def test_parse_ignores_unknown_lines_and_blank_lines_between_records():
    data = "  ok\ngarbage\nsome arbitrary text\n\nfoo=bar\n"

