def test_parse_quiet_suppresses_incompatibility_warning(monkeypatch, capsys):
    monkeypatch.setattr(
        "jc.parsers.nsd_control.jc.utils.is_compatible", lambda _compatible: False
    )

    assert parse("ok\n", raw=True, quiet=True) == [{"command": "ok"}]
    assert capsys.readouterr().err == ""

    assert parse("ok\n", raw=True, quiet=False) == [{"command": "ok"}]
    warning = capsys.readouterr().err
    assert "Warning" in warning
    assert "nsd_control" in warning

